export function getLexiconEntry(
  dictionary: Record<string, LexiconEntry>,
  wordId: string,
  fallbackLabel?: string,
  unitId?: string
): LexiconEntry {
  const normalized = wordId.toLowerCase().trim();
  if (unitId === "bathroom" && normalized === "shower") {
    return {
      ...dictionary.shower,
      arabic: "دُشّ",
      collocations: ["take a shower", "have a shower", "quick shower"],
      phrasalVerbs: [],
      sentences: [
        {
          context: "Daily routine",
          en: "I take a shower every morning.",
          ar: "أستحم كل صباح.",
        },
      ],
      exampleSentence: "I take a shower every morning.",
      exampleArabic: "أستحم كل صباح.",
    };
  }
  if (dictionary[normalized]) {
    return dictionary[normalized];
  }

  // Also check without hyphens or underscores
  const cleanKey = normalized.replace(/[-_]/g, "");
  const foundKey = Object.keys(dictionary).find(
    (k) => k.replace(/[-_]/g, "").toLowerCase() === cleanKey
  );
  if (foundKey) {
    return dictionary[foundKey];
  }

  // Check extended gloss dictionary
  if (EXTENDED_VOCABULARY_GLOSSES[normalized]) {
    const ext = EXTENDED_VOCABULARY_GLOSSES[normalized];
    const label = fallbackLabel || wordId.replace(/[-_]/g, " ");
    return {
      id: wordId,
      arabic: ext.ar,
      phonetic: ext.phonetic,
      partOfSpeech: ext.pos || "noun",
      collocations: ext.collocations || [],
      wordFamily: ext.wordFamily,
      register: ext.register,
      canDoScenario: ext.canDoScenario,
      sentences: [
        {
          context: "Everyday Usage",
          en: ext.exampleEn || `The ${label} is used in daily life.`,
          ar: ext.exampleAr || `يُسْتَخْدَمُ هَذَا العُنْصُرُ فِي الحَيَاةِ اليَوْمِيَّةِ.`,
        },
      ],
      exampleSentence: ext.exampleEn || `The ${label} is used in daily life.`,
      exampleArabic: ext.exampleAr || `يُسْتَخْدَمُ هَذَا العُنْصُرُ فِي الحَيَاةِ اليَوْمِيَّةِ.`,
    };
  }

  const label = fallbackLabel || wordId.replace(/[-_]/g, " ");
  // Grammatical whatever the label is: "This is a splint.", "These are
  // stitches.", "The word is “elevate”." The template this replaces was
  // `The ${label} is used in daily life.`, which produced "The Wash Hands is
  // used in daily life." for every verb phrase that reached it.
  const example = identifySentence(label);
  return {
    id: wordId,
    // Empty, not the English label. Both screens that show a gloss render it
    // inside `dir="rtl" lang="ar"`, so returning English here laid the word
    // out right-to-left and announced it to a screen reader as Arabic. An
    // absent translation is better said than faked.
    arabic: "",
    partOfSpeech: "noun",
    collocations: [],
    sentences: [
      {
        context: "Everyday Usage",
        en: example,
        ar: `يُسْتَخْدَمُ هَذَا العُنْصُرُ فِي الحَيَاةِ اليَوْمِيَّةِ.`,
      },
    ],
    exampleSentence: example,
    exampleArabic: `يُسْتَخْدَمُ هَذَا العُنْصُرُ فِي الحَيَاةِ اليَوْمِيَّةِ.`,
  };
}

/**
 * Whether an entry carries a real Arabic gloss.
 *
 * Screens use this to decide whether to render the translation block at all.
 * The test looks for Arabic script rather than for a non-empty string, because
 * the generated half of this dictionary has a history of filling the field
 * with English — 93 entries read "Heat Stroke (Arabic)" — and a check that
 * only looks for emptiness lets that straight through.
 */
export function hasArabicGloss(entry: Pick<LexiconEntry, "arabic">): boolean {
  return /[؀-ۿ]/.test(entry.arabic ?? "");
}
